const TOPICS = [{"name": "Operating systems", "arabic": "أنظمة التشغيل", "desc": "Processes, memory, threads, and the job of an OS.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4", "facts": [{"title": "What is the main role of an operating system?", "answer": "Manage hardware resources and provide services", "explain": "The OS coordinates CPU time, memory, files and I/O so applications can run."}, {"title": "What is a process?", "answer": "A program in execution", "explain": "A process has execution state and its own virtual address space."}, {"title": "How does a thread relate to a process?", "answer": "It is an execution unit within a process", "explain": "Threads in the same process share its address space and resources, but have their own execution stacks."}, {"title": "What describes deadlock?", "answer": "Tasks wait indefinitely for resources held by each other", "explain": "A circular wait can prevent every involved task from progressing."}, {"title": "What is virtual memory?", "answer": "An address-space abstraction that can use disk backing", "explain": "It separates virtual addresses from physical memory; paging can move less-used pages to disk. Disk is slower than RAM."}, {"title": "Which is a programming language rather than an OS?", "answer": "Python", "explain": "Python is a language; Linux, Windows and macOS are operating systems."}, {"title": "What distinguishes multiprocessing from multithreading?", "answer": "Multiple processes versus multiple threads within a process", "explain": "Processes normally have separate memory spaces; threads within one process share memory."}, {"title": "Which OS responsibility chooses which task runs next?", "answer": "CPU scheduling", "explain": "The scheduler allocates CPU time to runnable processes or threads."}]}, {"name": "Networks", "arabic": "الشبكات", "desc": "OSI layers, protocols, ports, and addresses.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3", "facts": [{"title": "How many layers are in the OSI model?", "answer": "7", "explain": "Bottom to top: Physical, Data Link, Network, Transport, Session, Presentation, Application."}, {"title": "Which OSI layer handles IP addressing and routing?", "answer": "Network", "explain": "Routers forward packets between networks using network-layer addresses."}, {"title": "Which OSI layer uses MAC addresses and frames?", "answer": "Data Link", "explain": "Ethernet frames and MAC addressing are associated with Layer 2; switches commonly work here."}, {"title": "Which OSI layer contains TCP and UDP?", "answer": "Transport", "explain": "Transport protocols use port numbers to distinguish application endpoints."}, {"title": "Which OSI layer handles data representation and compression?", "answer": "Presentation", "explain": "Presentation describes translation, encoding, compression and encryption in the conceptual OSI model."}, {"title": "Which OSI layer is closest to application services?", "answer": "Application", "explain": "HTTP, FTP, SMTP and DNS are application-layer protocols."}, {"title": "Which transport protocol offers reliable ordered byte delivery?", "answer": "TCP", "explain": "TCP is connection-oriented and uses acknowledgments and retransmissions; UDP provides datagrams without those guarantees."}, {"title": "Which service resolves a domain name to IP addresses?", "answer": "DNS", "explain": "DNS looks up records such as A for IPv4 and AAAA for IPv6."}, {"title": "Which service automatically supplies IP configuration?", "answer": "DHCP", "explain": "DHCP can supply an address, subnet mask, default gateway and DNS server settings."}, {"title": "What is a default gateway used for?", "answer": "Reaching destinations outside the local network", "explain": "A host sends traffic for nonlocal networks to its gateway, usually a router."}, {"title": "How many bits are in an IPv4 address?", "answer": "32", "explain": "IPv4 is 32 bits; IPv6 is 128 bits. An IP address identifies a network interface in its addressing context."}, {"title": "What is the conventional HTTPS port?", "answer": "443", "explain": "HTTP commonly uses 80; HTTPS commonly uses 443 and TLS."}, {"title": "What is the conventional HTTP port?", "answer": "80", "explain": "Plain HTTP commonly uses port 80."}, {"title": "Which protocol sends email between mail servers?", "answer": "SMTP", "explain": "SMTP conventionally uses port 25 for server-to-server transfer; mail submission often uses other ports."}, {"title": "Which protocol supports secure remote login?", "answer": "SSH", "explain": "SSH conventionally uses TCP port 22."}, {"title": "What is the conventional FTP control port?", "answer": "21", "explain": "Port 21 is the FTP control connection; data connections use separate ports."}, {"title": "Which protocol manages and monitors network devices?", "answer": "SNMP", "explain": "SNMP is used for network device management; SMTP is for mail."}, {"title": "How many layers are in the common TCP/IP model?", "answer": "4", "explain": "Application, Transport, Internet and Link/Network Access. Some teaching models split Link into two layers."}]}, {"name": "SQL & databases", "arabic": "قواعد البيانات", "desc": "Write queries, understand keys, and connect tables.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5", "facts": [{"title": "Which SQL statement selects every column from employees?", "answer": "SELECT * FROM employees;", "explain": "The asterisk means all columns; FROM specifies the table."}, {"title": "Which query selects employees older than 30?", "answer": "SELECT * FROM employees WHERE age > 30;", "explain": "WHERE filters rows; > excludes employees who are exactly 30."}, {"title": "Which query selects names with salary above 5000?", "answer": "SELECT name FROM employees WHERE salary > 5000;", "explain": "SELECT chooses columns; WHERE chooses matching rows."}, {"title": "Which SQL statement adds user Ali with ID 1?", "answer": "INSERT INTO users (id, name) VALUES (1, 'Ali');", "explain": "INSERT adds a row. String literals use single quotes in standard SQL."}, {"title": "Which query raises IT salaries by 10%?", "answer": "UPDATE employees SET salary = salary * 1.1 WHERE dept = 'IT';", "explain": "Multiply by 1.1 to retain the salary plus 10%. WHERE limits the update to IT employees."}, {"title": "How do you remove only the employee with ID 10?", "answer": "DELETE FROM employees WHERE id = 10;", "explain": "DELETE with WHERE removes matching rows. Without WHERE it removes all rows."}, {"title": "What does a primary key do?", "answer": "Uniquely identifies each row and cannot be NULL", "explain": "A primary key may consist of one or multiple columns."}, {"title": "What does a foreign key do?", "answer": "Enforces a reference to a key in a related table", "explain": "It supports referential integrity, for example an employee department_id referencing a department."}, {"title": "Which join returns only matching row combinations?", "answer": "INNER JOIN", "explain": "INNER JOIN returns combinations satisfying the join condition."}, {"title": "Which join keeps every row from the left table?", "answer": "LEFT JOIN", "explain": "LEFT JOIN includes unmatched left rows with NULL values for the right side."}, {"title": "Which SQL construct stacks compatible result sets?", "answer": "UNION", "explain": "JOIN combines related columns across tables; UNION combines result rows and removes duplicates by default."}, {"title": "Which SQL function counts all rows?", "answer": "COUNT(*)", "explain": "COUNT(*) counts rows, while COUNT(column) excludes NULL values in that column."}, {"title": "Which statement removes a table definition and its data?", "answer": "DROP TABLE employees;", "explain": "DROP removes the table itself. DELETE removes rows while preserving the table."}, {"title": "Which statement about TRUNCATE is generally correct?", "answer": "It removes all rows without a WHERE clause", "explain": "Exact rollback, identity and trigger behavior depends on the database. Avoid memorizing absolute transaction claims."}, {"title": "What is database normalization intended to reduce?", "answer": "Redundancy and update anomalies", "explain": "Normalization organizes data into appropriate related tables."}, {"title": "Are SQL keywords such as SELECT generally case-sensitive?", "answer": "No; identifier and string rules depend on the database", "explain": "Keywords are generally case-insensitive. Table names, quoted identifiers and string comparisons have database-specific rules."}]}, {"name": "Python & sockets", "arabic": "بايثون والاتصالات", "desc": "Files, processes, HTTP, TCP, UDP, and queues.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6", "facts": [{"title": "Which file mode opens an existing text file for reading?", "answer": "r", "explain": "Use with open(\"file.txt\", \"r\") as f: to close the file automatically when the block ends."}, {"title": "What does f.read() return for a text file?", "answer": "Remaining file contents as one string", "explain": "For a list of lines use f.readlines(); for line-by-line iteration use for line in f."}, {"title": "Which code iterates over file lines?", "answer": "for line in f:", "explain": "Iterating over a text file yields successive lines without loading the entire file into memory."}, {"title": "Which Unix-only os function creates a child process?", "answer": "os.fork()", "explain": "fork returns 0 in the child and the child PID in the parent. It is not available on Windows."}, {"title": "After pid = os.fork(), which branch identifies the child?", "answer": "if pid == 0:", "explain": "The child receives 0; the parent receives a positive child process ID on success."}, {"title": "Which socket type is used for TCP?", "answer": "socket.SOCK_STREAM", "explain": "SOCK_STREAM selects a stream socket, commonly TCP with AF_INET."}, {"title": "Which socket type is used for UDP?", "answer": "socket.SOCK_DGRAM", "explain": "SOCK_DGRAM selects a datagram socket, commonly UDP."}, {"title": "What does socket.AF_INET select?", "answer": "IPv4 addressing", "explain": "Address family and socket type are separate arguments. AF_INET6 selects IPv6."}, {"title": "Which method sends a datagram to an explicit destination?", "answer": "sock.sendto(data, address)", "explain": "For unconnected UDP, sendto accepts bytes and an address tuple. Connected UDP can also use send(); the note’s absolute rule is too broad."}, {"title": "Which call connects a TCP client before sending?", "answer": "sock.connect((host, port))", "explain": "Clients connect to a server; servers typically bind, listen and accept."}, {"title": "Which method is convenient for sending all bytes over TCP?", "answer": "sock.sendall(data)", "explain": "send() may send only part of the buffer; sendall() continues until complete or an error occurs."}, {"title": "Which standard-library module provides HTTPServer?", "answer": "http.server", "explain": "HTTPServer with BaseHTTPRequestHandler can handle requests by implementing methods such as do_GET."}, {"title": "Which HTTP response code indicates success?", "answer": "200", "explain": "A basic handler sends response 200, then headers, then bytes through self.wfile.write()."}, {"title": "Which data structure commonly connects a producer and consumer?", "answer": "A thread-safe queue", "explain": "queue.Queue lets producers put items and consumers get them safely across threads."}, {"title": "What does Thread.start() do?", "answer": "Starts execution of the thread target", "explain": "Constructing a Thread does not start it. start() schedules its target to run."}, {"title": "What does Thread.join() do?", "answer": "Waits for that thread to finish", "explain": "join waits; it does not forcibly terminate a thread."}, {"title": "Why can a consumer use None as a sentinel?", "answer": "To signal that no more items will arrive", "explain": "Choose a sentinel distinct from valid data. Send it after production completes so the consumer can exit."}, {"title": "Which Python collection is immutable?", "answer": "Tuple", "explain": "A tuple cannot have its element references reassigned; referenced mutable objects can still change."}, {"title": "Which keyword defines a Python function?", "answer": "def", "explain": "For example: def greet(): followed by an indented body."}, {"title": "Which loop prints numbers 1 through 5?", "answer": "for i in range(1, 6): print(i)", "explain": "range excludes its stop value, so use 6 to include 5."}, {"title": "Which Python constructs handle exceptions?", "answer": "try and except", "explain": "try runs code that may raise an exception; except handles matching exceptions."}]}, {"name": "Object-oriented programming", "arabic": "البرمجة الكائنية", "desc": "The four pillars and the Singleton pattern.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8", "facts": [{"title": "What does OOP stand for?", "answer": "Object-Oriented Programming", "explain": "Objects combine state and behavior; classes describe a type of object."}, {"title": "Which principle bundles state and behavior with controlled access?", "answer": "Encapsulation", "explain": "Encapsulation protects invariants through a defined interface, rather than exposing all internal state."}, {"title": "Which principle lets a class derive behavior from another class?", "answer": "Inheritance", "explain": "A subclass can reuse and extend a base class."}, {"title": "Which principle allows the same interface to have different implementations?", "answer": "Polymorphism", "explain": "Different objects can respond to the same operation differently, such as overridden draw() methods."}, {"title": "Which principle exposes essential behavior while hiding implementation detail?", "answer": "Abstraction", "explain": "Abstraction describes what an operation does while hiding how it is implemented."}, {"title": "What is the intent of the Singleton pattern?", "answer": "Restrict a class to one instance with a shared access point", "explain": "Singleton is a design pattern, separate from the four foundational OOP principles."}]}, {"name": "Data structures & algorithms", "arabic": "هياكل البيانات والخوارزميات", "desc": "Choose structures and recognize time complexity.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9", "facts": [{"title": "Which structure follows LIFO?", "answer": "Stack", "explain": "Last In, First Out: the last item pushed is the first popped. FILO means the same thing, so those cannot be separate answers in a fair MCQ."}, {"title": "Which structure follows FIFO?", "answer": "Queue", "explain": "First In, First Out: enqueue at the back and dequeue from the front."}, {"title": "Which structure naturally supports undo history?", "answer": "Stack", "explain": "The most recent action is undone first."}, {"title": "What is array access by index typically?", "answer": "O(1)", "explain": "An array computes an element address directly from its index."}, {"title": "What is worst-case linear search time?", "answer": "O(n)", "explain": "An unsuccessful search may examine all n elements."}, {"title": "What is binary search time on a sorted random-access array?", "answer": "O(log n)", "explain": "Each comparison halves the remaining search interval. Sorted order is required."}, {"title": "What is merge sort time complexity?", "answer": "O(n log n)", "explain": "Merge sort splits into halves and merges linear amounts of data across logarithmically many levels."}, {"title": "What is quicksort average time complexity?", "answer": "O(n log n)", "explain": "Average O(n log n), but worst-case O(n²). The average label matters."}, {"title": "What is bubble sort worst-case time complexity?", "answer": "O(n²)", "explain": "Repeated adjacent comparisons lead to quadratic work; an optimized version can be linear on already sorted input."}, {"title": "What is hash-table lookup average time under good hashing?", "answer": "O(1)", "explain": "Expected constant time assumes suitable hashing and load factor. Worst-case can be O(n)."}, {"title": "What is accessing position k in a singly linked list generally?", "answer": "O(n) in the worst case", "explain": "You must follow links from the head; there is no direct random access."}, {"title": "Which structure naturally represents a hierarchy?", "answer": "Tree", "explain": "A tree has parent-child relationships, such as folders or organization charts."}, {"title": "Which traversal typically uses a queue?", "answer": "Breadth-first search (BFS)", "explain": "BFS explores neighbors level by level. DFS typically uses recursion or an explicit stack."}]}, {"name": "Software engineering", "arabic": "هندسة البرمجيات", "desc": "Development stages, methods, modeling, and testing.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10", "facts": [{"title": "What does SDLC stand for?", "answer": "Software Development Life Cycle", "explain": "A common sequence is requirements, design, implementation, testing, deployment and maintenance."}, {"title": "What usually comes first in a basic SDLC?", "answer": "Requirements analysis", "explain": "Understand the problem and requirements before designing and building a solution."}, {"title": "Which approach emphasizes iterative delivery and collaboration?", "answer": "Agile", "explain": "Agile emphasizes feedback, adaptation and incremental value. Scrum, an Agile framework, uses sprints; not all Agile methods do."}, {"title": "Which framework divides work into timeboxed sprints?", "answer": "Scrum", "explain": "The recollections generalize sprints to all Agile. Scrum specifically uses timeboxed sprints."}, {"title": "What describes the Waterfall model?", "answer": "A largely sequential development model", "explain": "Phases typically progress in sequence; Agile approaches emphasize frequent feedback and adaptation."}, {"title": "Which tool is used for version control?", "answer": "Git", "explain": "Version control records changes and supports branches and collaboration."}, {"title": "What is the purpose of UML diagrams?", "answer": "Model system structure and behavior visually", "explain": "For example, class diagrams model structure and sequence diagrams model interactions."}, {"title": "What is the focus of unit testing?", "answer": "Small individual units of behavior", "explain": "Unit tests check focused units such as functions or classes in controlled conditions."}]}, {"name": "Cybersecurity", "arabic": "الأمن السيبراني", "desc": "CIA, identity, permissions, encryption, and hashing.", "source": "QuickReview pp. 3, 8–10", "facts": [{"title": "What are the three parts of the CIA triad?", "answer": "Confidentiality, Integrity, Availability", "explain": "Confidentiality limits disclosure; integrity protects correctness; availability ensures timely access."}, {"title": "Which CIA property protects against unauthorized disclosure?", "answer": "Confidentiality", "explain": "Encryption and access controls can help protect confidentiality."}, {"title": "Which CIA property concerns unauthorized changes?", "answer": "Integrity", "explain": "Integrity concerns data remaining accurate and protected from unauthorized modification."}, {"title": "What does authentication establish?", "answer": "Who you are", "explain": "Authentication verifies identity, for example with a password or security key."}, {"title": "What does authorization establish?", "answer": "What an identity is permitted to do", "explain": "Authorization checks permissions after or alongside identity verification."}, {"title": "Which statement best describes encryption?", "answer": "Data can be recovered with the appropriate key", "explain": "Encryption transforms plaintext into ciphertext; decryption with the right key recovers plaintext."}, {"title": "Which statement best describes a cryptographic hash?", "answer": "A one-way digest designed to resist inversion", "explain": "Hashing is not encryption. Secure password storage uses salted, slow password-hashing schemes; hashes can still be guessed by trying candidate inputs."}]}];
const QUESTIONS = [{"id": 0, "topic": 0, "prompt": "What is the main role of an operating system?", "answer": "Manage hardware resources and provide services", "options": ["Manage hardware resources and provide services", "Design web pages", "Store only images", "Replace application software"], "explain": "The OS coordinates CPU time, memory, files and I/O so applications can run.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 1, "topic": 0, "prompt": "What is a process?", "answer": "A program in execution", "options": ["A program in execution", "A file extension", "A network address", "A database column"], "explain": "A process has execution state and its own virtual address space.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 2, "topic": 0, "prompt": "How does a thread relate to a process?", "answer": "It is an execution unit within a process", "options": ["It is an execution unit within a process", "It is always a separate computer", "It replaces the OS", "It is a disk partition"], "explain": "Threads in the same process share its address space and resources, but have their own execution stacks.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 3, "topic": 0, "prompt": "What describes deadlock?", "answer": "Tasks wait indefinitely for resources held by each other", "options": ["Tasks wait indefinitely for resources held by each other", "Tasks all finish successfully", "The CPU becomes faster", "A file is copied"], "explain": "A circular wait can prevent every involved task from progressing.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 4, "topic": 0, "prompt": "What is virtual memory?", "answer": "An address-space abstraction that can use disk backing", "options": ["An address-space abstraction that can use disk backing", "Extra physical RAM installed automatically", "A network buffer only", "A faster CPU cache"], "explain": "It separates virtual addresses from physical memory; paging can move less-used pages to disk. Disk is slower than RAM.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 5, "topic": 0, "prompt": "Which is a programming language rather than an OS?", "answer": "Python", "options": ["Python", "Linux", "Windows", "macOS"], "explain": "Python is a language; Linux, Windows and macOS are operating systems.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 6, "topic": 0, "prompt": "What distinguishes multiprocessing from multithreading?", "answer": "Multiple processes versus multiple threads within a process", "options": ["Multiple processes versus multiple threads within a process", "Multiple screens versus one screen", "SQL versus Python", "Encryption versus hashing"], "explain": "Processes normally have separate memory spaces; threads within one process share memory.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 7, "topic": 0, "prompt": "Which OS responsibility chooses which task runs next?", "answer": "CPU scheduling", "options": ["CPU scheduling", "DNS resolution", "SQL normalization", "Image compression"], "explain": "The scheduler allocates CPU time to runnable processes or threads.", "source": "QuickReview pp. 1, 4, 8–10; IT assment pp. 1, 4"}, {"id": 8, "topic": 1, "prompt": "How many layers are in the OSI model?", "answer": "7", "options": ["7", "4", "5", "8"], "explain": "Bottom to top: Physical, Data Link, Network, Transport, Session, Presentation, Application.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 9, "topic": 1, "prompt": "Which OSI layer handles IP addressing and routing?", "answer": "Network", "options": ["Network", "Transport", "Application", "Presentation"], "explain": "Routers forward packets between networks using network-layer addresses.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 10, "topic": 1, "prompt": "Which OSI layer uses MAC addresses and frames?", "answer": "Data Link", "options": ["Data Link", "Network", "Session", "Application"], "explain": "Ethernet frames and MAC addressing are associated with Layer 2; switches commonly work here.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 11, "topic": 1, "prompt": "Which OSI layer contains TCP and UDP?", "answer": "Transport", "options": ["Transport", "Physical", "Presentation", "Data Link"], "explain": "Transport protocols use port numbers to distinguish application endpoints.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 12, "topic": 1, "prompt": "Which OSI layer handles data representation and compression?", "answer": "Presentation", "options": ["Presentation", "Physical", "Network", "Session"], "explain": "Presentation describes translation, encoding, compression and encryption in the conceptual OSI model.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 13, "topic": 1, "prompt": "Which OSI layer is closest to application services?", "answer": "Application", "options": ["Application", "Physical", "Data Link", "Network"], "explain": "HTTP, FTP, SMTP and DNS are application-layer protocols.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 14, "topic": 1, "prompt": "Which transport protocol offers reliable ordered byte delivery?", "answer": "TCP", "options": ["TCP", "UDP", "IP", "ARP"], "explain": "TCP is connection-oriented and uses acknowledgments and retransmissions; UDP provides datagrams without those guarantees.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 15, "topic": 1, "prompt": "Which service resolves a domain name to IP addresses?", "answer": "DNS", "options": ["DNS", "DHCP", "FTP", "SSH"], "explain": "DNS looks up records such as A for IPv4 and AAAA for IPv6.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 16, "topic": 1, "prompt": "Which service automatically supplies IP configuration?", "answer": "DHCP", "options": ["DHCP", "DNS", "SMTP", "HTTP"], "explain": "DHCP can supply an address, subnet mask, default gateway and DNS server settings.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 17, "topic": 1, "prompt": "What is a default gateway used for?", "answer": "Reaching destinations outside the local network", "options": ["Reaching destinations outside the local network", "Encrypting a file", "Sorting packets by size", "Creating database tables"], "explain": "A host sends traffic for nonlocal networks to its gateway, usually a router.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 18, "topic": 1, "prompt": "How many bits are in an IPv4 address?", "answer": "32", "options": ["32", "16", "64", "128"], "explain": "IPv4 is 32 bits; IPv6 is 128 bits. An IP address identifies a network interface in its addressing context.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 19, "topic": 1, "prompt": "What is the conventional HTTPS port?", "answer": "443", "options": ["443", "80", "21", "25"], "explain": "HTTP commonly uses 80; HTTPS commonly uses 443 and TLS.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 20, "topic": 1, "prompt": "What is the conventional HTTP port?", "answer": "80", "options": ["80", "443", "22", "53"], "explain": "Plain HTTP commonly uses port 80.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 21, "topic": 1, "prompt": "Which protocol sends email between mail servers?", "answer": "SMTP", "options": ["SMTP", "FTP", "SNMP", "DHCP"], "explain": "SMTP conventionally uses port 25 for server-to-server transfer; mail submission often uses other ports.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 22, "topic": 1, "prompt": "Which protocol supports secure remote login?", "answer": "SSH", "options": ["SSH", "FTP", "HTTP", "SNMP"], "explain": "SSH conventionally uses TCP port 22.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 23, "topic": 1, "prompt": "What is the conventional FTP control port?", "answer": "21", "options": ["21", "22", "25", "443"], "explain": "Port 21 is the FTP control connection; data connections use separate ports.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 24, "topic": 1, "prompt": "Which protocol manages and monitors network devices?", "answer": "SNMP", "options": ["SNMP", "SMTP", "FTP", "DHCP"], "explain": "SNMP is used for network device management; SMTP is for mail.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 25, "topic": 1, "prompt": "How many layers are in the common TCP/IP model?", "answer": "4", "options": ["4", "7", "2", "6"], "explain": "Application, Transport, Internet and Link/Network Access. Some teaching models split Link into two layers.", "source": "QuickReview pp. 4–5, 12, 17–18, 24–26; IT assment pp. 2–3"}, {"id": 26, "topic": 2, "prompt": "Which SQL statement selects every column from employees?", "answer": "SELECT * FROM employees;", "options": ["SELECT * FROM employees;", "GET ALL employees;", "SHOW employees;", "SELECT employees;"], "explain": "The asterisk means all columns; FROM specifies the table.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 27, "topic": 2, "prompt": "Which query selects employees older than 30?", "answer": "SELECT * FROM employees WHERE age > 30;", "options": ["SELECT * FROM employees WHERE age > 30;", "SELECT * FROM employees WHERE age < 30;", "DELETE FROM employees WHERE age > 30;", "SELECT age > 30;"], "explain": "WHERE filters rows; > excludes employees who are exactly 30.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 28, "topic": 2, "prompt": "Which query selects names with salary above 5000?", "answer": "SELECT name FROM employees WHERE salary > 5000;", "options": ["SELECT name FROM employees WHERE salary > 5000;", "SELECT name FROM employees WHERE salary < 5000;", "UPDATE employees SET salary = 5000;", "DELETE FROM employees;"], "explain": "SELECT chooses columns; WHERE chooses matching rows.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 29, "topic": 2, "prompt": "Which SQL statement adds user Ali with ID 1?", "answer": "INSERT INTO users (id, name) VALUES (1, 'Ali');", "options": ["INSERT INTO users (id, name) VALUES (1, 'Ali');", "UPDATE users SET id = 1;", "INSERT users WHERE name = Ali;", "SELECT Ali FROM users;"], "explain": "INSERT adds a row. String literals use single quotes in standard SQL.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 30, "topic": 2, "prompt": "Which query raises IT salaries by 10%?", "answer": "UPDATE employees SET salary = salary * 1.1 WHERE dept = 'IT';", "options": ["UPDATE employees SET salary = salary * 1.1 WHERE dept = 'IT';", "UPDATE employees SET salary = salary * 0.1;", "SELECT salary * 1.1 FROM employees;", "DELETE FROM employees WHERE dept = 'IT';"], "explain": "Multiply by 1.1 to retain the salary plus 10%. WHERE limits the update to IT employees.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 31, "topic": 2, "prompt": "How do you remove only the employee with ID 10?", "answer": "DELETE FROM employees WHERE id = 10;", "options": ["DELETE FROM employees WHERE id = 10;", "DROP TABLE employees;", "DELETE FROM employees;", "TRUNCATE TABLE employees;"], "explain": "DELETE with WHERE removes matching rows. Without WHERE it removes all rows.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 32, "topic": 2, "prompt": "What does a primary key do?", "answer": "Uniquely identifies each row and cannot be NULL", "options": ["Uniquely identifies each row and cannot be NULL", "Encrypts every column", "Always refers to another table", "Allows duplicate row identifiers"], "explain": "A primary key may consist of one or multiple columns.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 33, "topic": 2, "prompt": "What does a foreign key do?", "answer": "Enforces a reference to a key in a related table", "options": ["Enforces a reference to a key in a related table", "Always uniquely identifies every row locally", "Sorts rows permanently", "Encrypts records"], "explain": "It supports referential integrity, for example an employee department_id referencing a department.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 34, "topic": 2, "prompt": "Which join returns only matching row combinations?", "answer": "INNER JOIN", "options": ["INNER JOIN", "LEFT JOIN", "FULL OUTER JOIN", "CROSS JOIN"], "explain": "INNER JOIN returns combinations satisfying the join condition.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 35, "topic": 2, "prompt": "Which join keeps every row from the left table?", "answer": "LEFT JOIN", "options": ["LEFT JOIN", "INNER JOIN", "RIGHT JOIN", "CROSS JOIN"], "explain": "LEFT JOIN includes unmatched left rows with NULL values for the right side.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 36, "topic": 2, "prompt": "Which SQL construct stacks compatible result sets?", "answer": "UNION", "options": ["UNION", "JOIN", "WHERE", "UPDATE"], "explain": "JOIN combines related columns across tables; UNION combines result rows and removes duplicates by default.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 37, "topic": 2, "prompt": "Which SQL function counts all rows?", "answer": "COUNT(*)", "options": ["COUNT(*)", "SUM(*)", "ROWS()", "TOTAL(*)"], "explain": "COUNT(*) counts rows, while COUNT(column) excludes NULL values in that column.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 38, "topic": 2, "prompt": "Which statement removes a table definition and its data?", "answer": "DROP TABLE employees;", "options": ["DROP TABLE employees;", "DELETE FROM employees;", "SELECT * FROM employees;", "UPDATE employees SET id = 1;"], "explain": "DROP removes the table itself. DELETE removes rows while preserving the table.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 39, "topic": 2, "prompt": "Which statement about TRUNCATE is generally correct?", "answer": "It removes all rows without a WHERE clause", "options": ["It removes all rows without a WHERE clause", "It filters rows with WHERE", "It always removes the table definition", "It selects only distinct rows"], "explain": "Exact rollback, identity and trigger behavior depends on the database. Avoid memorizing absolute transaction claims.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 40, "topic": 2, "prompt": "What is database normalization intended to reduce?", "answer": "Redundancy and update anomalies", "options": ["Redundancy and update anomalies", "The number of users only", "All primary keys", "All relations between data"], "explain": "Normalization organizes data into appropriate related tables.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 41, "topic": 2, "prompt": "Are SQL keywords such as SELECT generally case-sensitive?", "answer": "No; identifier and string rules depend on the database", "options": ["No; identifier and string rules depend on the database", "Yes, always", "Only SELECT is case-sensitive", "Strings are never case-sensitive"], "explain": "Keywords are generally case-insensitive. Table names, quoted identifiers and string comparisons have database-specific rules.", "source": "QuickReview pp. 1, 5, 10, 13, 18; IT assment pp. 1, 5"}, {"id": 42, "topic": 3, "prompt": "Which file mode opens an existing text file for reading?", "answer": "r", "options": ["r", "w", "a", "x"], "explain": "Use with open(\"file.txt\", \"r\") as f: to close the file automatically when the block ends.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 43, "topic": 3, "prompt": "What does f.read() return for a text file?", "answer": "Remaining file contents as one string", "options": ["Remaining file contents as one string", "A list of lines automatically", "Only the file name", "A new process"], "explain": "For a list of lines use f.readlines(); for line-by-line iteration use for line in f.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 44, "topic": 3, "prompt": "Which code iterates over file lines?", "answer": "for line in f:", "options": ["for line in f:", "for line in f.name:", "while f.close():", "for line in open:"], "explain": "Iterating over a text file yields successive lines without loading the entire file into memory.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 45, "topic": 3, "prompt": "Which Unix-only os function creates a child process?", "answer": "os.fork()", "options": ["os.fork()", "os.thread()", "os.process()", "os.spawn_thread()"], "explain": "fork returns 0 in the child and the child PID in the parent. It is not available on Windows.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 46, "topic": 3, "prompt": "After pid = os.fork(), which branch identifies the child?", "answer": "if pid == 0:", "options": ["if pid == 0:", "if pid > 0:", "if pid is None:", "if pid < 0:"], "explain": "The child receives 0; the parent receives a positive child process ID on success.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 47, "topic": 3, "prompt": "Which socket type is used for TCP?", "answer": "socket.SOCK_STREAM", "options": ["socket.SOCK_STREAM", "socket.SOCK_DGRAM", "socket.AF_INET", "socket.TCP_ONLY"], "explain": "SOCK_STREAM selects a stream socket, commonly TCP with AF_INET.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 48, "topic": 3, "prompt": "Which socket type is used for UDP?", "answer": "socket.SOCK_DGRAM", "options": ["socket.SOCK_DGRAM", "socket.SOCK_STREAM", "socket.AF_INET", "socket.UDP_ONLY"], "explain": "SOCK_DGRAM selects a datagram socket, commonly UDP.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 49, "topic": 3, "prompt": "What does socket.AF_INET select?", "answer": "IPv4 addressing", "options": ["IPv4 addressing", "TCP transport", "UDP transport", "IPv6 addressing"], "explain": "Address family and socket type are separate arguments. AF_INET6 selects IPv6.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 50, "topic": 3, "prompt": "Which method sends a datagram to an explicit destination?", "answer": "sock.sendto(data, address)", "options": ["sock.sendto(data, address)", "sock.listen(data)", "sock.accept(data)", "sock.readto(data)"], "explain": "For unconnected UDP, sendto accepts bytes and an address tuple. Connected UDP can also use send(); the note’s absolute rule is too broad.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 51, "topic": 3, "prompt": "Which call connects a TCP client before sending?", "answer": "sock.connect((host, port))", "options": ["sock.connect((host, port))", "sock.listen((host, port))", "sock.accept((host, port))", "sock.bind_remote(host)"], "explain": "Clients connect to a server; servers typically bind, listen and accept.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 52, "topic": 3, "prompt": "Which method is convenient for sending all bytes over TCP?", "answer": "sock.sendall(data)", "options": ["sock.sendall(data)", "sock.listen(data)", "sock.accept(data)", "sock.close(data)"], "explain": "send() may send only part of the buffer; sendall() continues until complete or an error occurs.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 53, "topic": 3, "prompt": "Which standard-library module provides HTTPServer?", "answer": "http.server", "options": ["http.server", "socket.http", "os.http", "queue.server"], "explain": "HTTPServer with BaseHTTPRequestHandler can handle requests by implementing methods such as do_GET.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 54, "topic": 3, "prompt": "Which HTTP response code indicates success?", "answer": "200", "options": ["200", "404", "500", "403"], "explain": "A basic handler sends response 200, then headers, then bytes through self.wfile.write().", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 55, "topic": 3, "prompt": "Which data structure commonly connects a producer and consumer?", "answer": "A thread-safe queue", "options": ["A thread-safe queue", "A CSS stylesheet", "An SQL view only", "An immutable number"], "explain": "queue.Queue lets producers put items and consumers get them safely across threads.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 56, "topic": 3, "prompt": "What does Thread.start() do?", "answer": "Starts execution of the thread target", "options": ["Starts execution of the thread target", "Waits for the thread to finish", "Deletes the queue", "Calls the target only after join"], "explain": "Constructing a Thread does not start it. start() schedules its target to run.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 57, "topic": 3, "prompt": "What does Thread.join() do?", "answer": "Waits for that thread to finish", "options": ["Waits for that thread to finish", "Starts a new process", "Adds an item to a queue", "Stops any thread immediately"], "explain": "join waits; it does not forcibly terminate a thread.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 58, "topic": 3, "prompt": "Why can a consumer use None as a sentinel?", "answer": "To signal that no more items will arrive", "options": ["To signal that no more items will arrive", "To sort the queue", "To restart the producer", "To make get() nonblocking"], "explain": "Choose a sentinel distinct from valid data. Send it after production completes so the consumer can exit.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 59, "topic": 3, "prompt": "Which Python collection is immutable?", "answer": "Tuple", "options": ["Tuple", "List", "Dictionary", "Set"], "explain": "A tuple cannot have its element references reassigned; referenced mutable objects can still change.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 60, "topic": 3, "prompt": "Which keyword defines a Python function?", "answer": "def", "options": ["def", "function", "define", "func"], "explain": "For example: def greet(): followed by an indented body.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 61, "topic": 3, "prompt": "Which loop prints numbers 1 through 5?", "answer": "for i in range(1, 6): print(i)", "options": ["for i in range(1, 6): print(i)", "for i in range(1, 5): print(i)", "for i in range(5): print(i)", "for i in range(6, 1): print(i)"], "explain": "range excludes its stop value, so use 6 to include 5.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 62, "topic": 3, "prompt": "Which Python constructs handle exceptions?", "answer": "try and except", "options": ["try and except", "if and import", "for and class", "with and def"], "explain": "try runs code that may raise an exception; except handles matching exceptions.", "source": "Note 17 Jan 2026 (2) pp. 2–4; QuickReview pp. 2–3, 6–7, 13–14, 19; IT assment pp. 1–2, 6"}, {"id": 63, "topic": 4, "prompt": "What does OOP stand for?", "answer": "Object-Oriented Programming", "options": ["Object-Oriented Programming", "Open Operating Process", "Object Ordered Protocol", "Online Output Program"], "explain": "Objects combine state and behavior; classes describe a type of object.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8"}, {"id": 64, "topic": 4, "prompt": "Which principle bundles state and behavior with controlled access?", "answer": "Encapsulation", "options": ["Encapsulation", "Inheritance", "Polymorphism", "Sorting"], "explain": "Encapsulation protects invariants through a defined interface, rather than exposing all internal state.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8"}, {"id": 65, "topic": 4, "prompt": "Which principle lets a class derive behavior from another class?", "answer": "Inheritance", "options": ["Inheritance", "Encapsulation", "Hashing", "Normalization"], "explain": "A subclass can reuse and extend a base class.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8"}, {"id": 66, "topic": 4, "prompt": "Which principle allows the same interface to have different implementations?", "answer": "Polymorphism", "options": ["Polymorphism", "Inheritance only", "Encryption", "Scheduling"], "explain": "Different objects can respond to the same operation differently, such as overridden draw() methods.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8"}, {"id": 67, "topic": 4, "prompt": "Which principle exposes essential behavior while hiding implementation detail?", "answer": "Abstraction", "options": ["Abstraction", "Deadlock", "Normalization", "Multiprocessing"], "explain": "Abstraction describes what an operation does while hiding how it is implemented.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8"}, {"id": 68, "topic": 4, "prompt": "What is the intent of the Singleton pattern?", "answer": "Restrict a class to one instance with a shared access point", "options": ["Restrict a class to one instance with a shared access point", "Create an unlimited number of threads", "Make every method private", "Replace inheritance"], "explain": "Singleton is a design pattern, separate from the four foundational OOP principles.", "source": "QuickReview pp. 2, 6, 14, 19–20; IT assment pp. 3, 8"}, {"id": 69, "topic": 5, "prompt": "Which structure follows LIFO?", "answer": "Stack", "options": ["Stack", "Queue", "Hash table", "Tree"], "explain": "Last In, First Out: the last item pushed is the first popped. FILO means the same thing, so those cannot be separate answers in a fair MCQ.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 70, "topic": 5, "prompt": "Which structure follows FIFO?", "answer": "Queue", "options": ["Queue", "Stack", "Binary tree", "Hash table"], "explain": "First In, First Out: enqueue at the back and dequeue from the front.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 71, "topic": 5, "prompt": "Which structure naturally supports undo history?", "answer": "Stack", "options": ["Stack", "Queue", "Router", "SQL view"], "explain": "The most recent action is undone first.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 72, "topic": 5, "prompt": "What is array access by index typically?", "answer": "O(1)", "options": ["O(1)", "O(n)", "O(log n)", "O(n²)"], "explain": "An array computes an element address directly from its index.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 73, "topic": 5, "prompt": "What is worst-case linear search time?", "answer": "O(n)", "options": ["O(n)", "O(1)", "O(log n)", "O(n log n)"], "explain": "An unsuccessful search may examine all n elements.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 74, "topic": 5, "prompt": "What is binary search time on a sorted random-access array?", "answer": "O(log n)", "options": ["O(log n)", "O(n²)", "O(n)", "O(1)"], "explain": "Each comparison halves the remaining search interval. Sorted order is required.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 75, "topic": 5, "prompt": "What is merge sort time complexity?", "answer": "O(n log n)", "options": ["O(n log n)", "O(1)", "O(log n)", "O(n²)"], "explain": "Merge sort splits into halves and merges linear amounts of data across logarithmically many levels.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 76, "topic": 5, "prompt": "What is quicksort average time complexity?", "answer": "O(n log n)", "options": ["O(n log n)", "O(1)", "O(log n)", "O(n³)"], "explain": "Average O(n log n), but worst-case O(n²). The average label matters.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 77, "topic": 5, "prompt": "What is bubble sort worst-case time complexity?", "answer": "O(n²)", "options": ["O(n²)", "O(log n)", "O(1)", "O(n log n)"], "explain": "Repeated adjacent comparisons lead to quadratic work; an optimized version can be linear on already sorted input.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 78, "topic": 5, "prompt": "What is hash-table lookup average time under good hashing?", "answer": "O(1)", "options": ["O(1)", "O(n log n)", "O(log n)", "O(n²)"], "explain": "Expected constant time assumes suitable hashing and load factor. Worst-case can be O(n).", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 79, "topic": 5, "prompt": "What is accessing position k in a singly linked list generally?", "answer": "O(n) in the worst case", "options": ["O(n) in the worst case", "O(1) always", "O(log n) always", "O(n²) always"], "explain": "You must follow links from the head; there is no direct random access.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 80, "topic": 5, "prompt": "Which structure naturally represents a hierarchy?", "answer": "Tree", "options": ["Tree", "Stack only", "Queue only", "Flat array only"], "explain": "A tree has parent-child relationships, such as folders or organization charts.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 81, "topic": 5, "prompt": "Which traversal typically uses a queue?", "answer": "Breadth-first search (BFS)", "options": ["Breadth-first search (BFS)", "Depth-first search (DFS)", "Binary search", "Quicksort"], "explain": "BFS explores neighbors level by level. DFS typically uses recursion or an explicit stack.", "source": "QuickReview pp. 2, 6, 9, 11, 15, 20, 23; IT assment pp. 2–3, 6–7, 9"}, {"id": 82, "topic": 6, "prompt": "What does SDLC stand for?", "answer": "Software Development Life Cycle", "options": ["Software Development Life Cycle", "System Data Link Code", "Software Design Logic Class", "Secure Device Login Control"], "explain": "A common sequence is requirements, design, implementation, testing, deployment and maintenance.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 83, "topic": 6, "prompt": "What usually comes first in a basic SDLC?", "answer": "Requirements analysis", "options": ["Requirements analysis", "Deployment", "Maintenance", "Implementation"], "explain": "Understand the problem and requirements before designing and building a solution.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 84, "topic": 6, "prompt": "Which approach emphasizes iterative delivery and collaboration?", "answer": "Agile", "options": ["Agile", "Waterfall", "Bubble sort", "Normalization"], "explain": "Agile emphasizes feedback, adaptation and incremental value. Scrum, an Agile framework, uses sprints; not all Agile methods do.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 85, "topic": 6, "prompt": "Which framework divides work into timeboxed sprints?", "answer": "Scrum", "options": ["Scrum", "Every Agile method without exception", "FTP", "Git"], "explain": "The recollections generalize sprints to all Agile. Scrum specifically uses timeboxed sprints.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 86, "topic": 6, "prompt": "What describes the Waterfall model?", "answer": "A largely sequential development model", "options": ["A largely sequential development model", "A network routing protocol", "A data structure", "A hashing algorithm"], "explain": "Phases typically progress in sequence; Agile approaches emphasize frequent feedback and adaptation.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 87, "topic": 6, "prompt": "Which tool is used for version control?", "answer": "Git", "options": ["Git", "HTTP", "DHCP", "Python queue"], "explain": "Version control records changes and supports branches and collaboration.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 88, "topic": 6, "prompt": "What is the purpose of UML diagrams?", "answer": "Model system structure and behavior visually", "options": ["Model system structure and behavior visually", "Encrypt database rows", "Assign IP addresses", "Compile Python"], "explain": "For example, class diagrams model structure and sequence diagrams model interactions.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 89, "topic": 6, "prompt": "What is the focus of unit testing?", "answer": "Small individual units of behavior", "options": ["Small individual units of behavior", "Only the complete production system", "Only network hardware", "Only interface colors"], "explain": "Unit tests check focused units such as functions or classes in controlled conditions.", "source": "QuickReview pp. 3, 7, 10, 20–21; IT assment pp. 3–4, 9–10"}, {"id": 90, "topic": 7, "prompt": "What are the three parts of the CIA triad?", "answer": "Confidentiality, Integrity, Availability", "options": ["Confidentiality, Integrity, Availability", "Control, Identity, Access", "Code, Internet, Application", "Confidentiality, Inspection, Authentication"], "explain": "Confidentiality limits disclosure; integrity protects correctness; availability ensures timely access.", "source": "QuickReview pp. 3, 8–10"}, {"id": 91, "topic": 7, "prompt": "Which CIA property protects against unauthorized disclosure?", "answer": "Confidentiality", "options": ["Confidentiality", "Integrity", "Availability", "Scheduling"], "explain": "Encryption and access controls can help protect confidentiality.", "source": "QuickReview pp. 3, 8–10"}, {"id": 92, "topic": 7, "prompt": "Which CIA property concerns unauthorized changes?", "answer": "Integrity", "options": ["Integrity", "Availability", "Confidentiality", "Polymorphism"], "explain": "Integrity concerns data remaining accurate and protected from unauthorized modification.", "source": "QuickReview pp. 3, 8–10"}, {"id": 93, "topic": 7, "prompt": "What does authentication establish?", "answer": "Who you are", "options": ["Who you are", "What you are allowed to access", "How fast data travels", "Whether data is sorted"], "explain": "Authentication verifies identity, for example with a password or security key.", "source": "QuickReview pp. 3, 8–10"}, {"id": 94, "topic": 7, "prompt": "What does authorization establish?", "answer": "What an identity is permitted to do", "options": ["What an identity is permitted to do", "Who you are", "Which cable is connected", "How code is compiled"], "explain": "Authorization checks permissions after or alongside identity verification.", "source": "QuickReview pp. 3, 8–10"}, {"id": 95, "topic": 7, "prompt": "Which statement best describes encryption?", "answer": "Data can be recovered with the appropriate key", "options": ["Data can be recovered with the appropriate key", "It is always a one-way digest", "It prevents every outage", "It removes the need for authorization"], "explain": "Encryption transforms plaintext into ciphertext; decryption with the right key recovers plaintext.", "source": "QuickReview pp. 3, 8–10"}, {"id": 96, "topic": 7, "prompt": "Which statement best describes a cryptographic hash?", "answer": "A one-way digest designed to resist inversion", "options": ["A one-way digest designed to resist inversion", "Encryption that is decrypted with a public key", "A reversible file compressor", "A guaranteed unique number for all inputs"], "explain": "Hashing is not encryption. Secure password storage uses salted, slow password-hashing schemes; hashes can still be guessed by trying candidate inputs.", "source": "QuickReview pp. 3, 8–10"}];
const CODES = [{"title": "Read a file line by line", "topic": "Files", "source": "Note p. 2", "code": "with open(\"file.txt\", \"r\") as f:\n    for line in f:\n        print(line, end=\"\")", "note": "The with block closes the file automatically. end=\"\" avoids adding a second newline."}, {"title": "Create a Unix child process", "topic": "Processes", "source": "Note p. 2", "code": "import os\n\npid = os.fork()  # Unix only\nif pid == 0:\n    print(\"Child process\")\nelse:\n    print(\"Parent process\")", "note": "Know the return values: child = 0, parent = child PID. This example cannot run on Windows."}, {"title": "TCP client", "topic": "Sockets", "source": "Note pp. 3–4", "code": "import socket\n\nwith socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:\n    sock.connect((\"localhost\", 9999))\n    sock.sendall(b\"Hello\")", "note": "AF_INET = IPv4. SOCK_STREAM = TCP. A listening server is needed. sendall handles partial sends."}, {"title": "Send a UDP datagram", "topic": "Sockets", "source": "Note p. 3", "code": "import socket\n\nwith socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:\n    sock.sendto(b\"Hello\", (\"localhost\", 9999))", "note": "SOCK_DGRAM = UDP. sendto includes the destination; UDP does not guarantee delivery or ordering. Connected UDP can also use send()."}, {"title": "Handle an HTTP GET request", "topic": "HTTP", "source": "Note p. 2", "code": "from http.server import HTTPServer, BaseHTTPRequestHandler\n\nclass Handler(BaseHTTPRequestHandler):\n    def do_GET(self):\n        self.send_response(200)\n        self.send_header(\"Content-Type\", \"text/plain\")\n        self.end_headers()\n        self.wfile.write(b\"Hello\")\n\nserver = HTTPServer((\"localhost\", 8080), Handler)\nserver.serve_forever()", "note": "send_response sets the status; end_headers finishes the headers; wfile.write sends bytes. Recognize the sequence."}, {"title": "Producer and consumer", "topic": "Threads", "source": "Note p. 4", "code": "import threading\nimport queue\n\nq = queue.Queue()\n\ndef producer():\n    for i in range(5):\n        q.put(i)\n\ndef consumer():\n    while True:\n        item = q.get()\n        if item is None:\n            break\n        print(\"Consumed\", item)\n\nt1 = threading.Thread(target=producer)\nt2 = threading.Thread(target=consumer)\nt1.start()\nt2.start()\nt1.join()\nq.put(None)\nt2.join()", "note": "Start both threads, wait for production, enqueue the sentinel, then wait for the consumer. Without a sentinel the consumer could wait forever."}, {"title": "Filter, update, and join in SQL", "topic": "SQL", "source": "QuickReview pp. 5, 10, 13, 18", "code": "SELECT name FROM employees WHERE salary > 5000;\n\nUPDATE employees\nSET salary = salary * 1.1\nWHERE dept = 'IT';\n\nSELECT e.name, d.name AS department\nFROM employees AS e\nINNER JOIN departments AS d ON e.department_id = d.id;", "note": "SELECT chooses columns, WHERE filters rows, SET changes values, and JOIN relates tables. The JOIN example extends the notes with explicit syntax."}];